pragma solidity 0.7.5;

import "@openzeppelin/contracts/math/Math.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import "../interfaces/IStakingRewards.sol";
import "../interfaces/Pausable.sol";
import "../interfaces/RewardsDistributionRecipient.sol";
import "../interfaces/OnDemandToken.sol";
import "../interfaces/MintableToken.sol";

contract StakingRewards is IStakingRewards, RewardsDistributionRecipient, ReentrancyGuard, Pausable {
using SafeERC20 for IERC20;

struct Times {
uint32 periodFinish;
uint32 rewardsDuration;
uint32 lastUpdateTime;
uint96 totalRewardsSupply;
}

uint256 public immutable maxEverTotalRewards;

IERC20 public immutable rewardsToken;
IERC20 public immutable stakingToken;

uint256 public rewardRate = 0;
uint256 public rewardPerTokenStored;

mapping(address => uint256) public userRewardPerTokenPaid;
mapping(address => uint256) public rewards;

uint256 private _totalSupply;
mapping(address => uint256) private _balances;

Times public timeData;
bool public stopped;

event RewardAdded(uint256 reward);
event Staked(address indexed user, uint256 amount);
event Withdrawn(address indexed user, uint256 amount);
event RewardPaid(address indexed user, uint256 reward);
event RewardsDurationUpdated(uint256 newDuration);
event FarmingFinished();

modifier whenActive() {
require(!stopped, "farming is stopped");
_;
}

modifier updateReward(address account) virtual {
uint256 newRewardPerTokenStored = rewardPerToken();
rewardPerTokenStored = newRewardPerTokenStored;
timeData.lastUpdateTime = uint32(lastTimeRewardApplicable());

if (account != address(0)) {
rewards[account] = earned(account);
userRewardPerTokenPaid[account] = newRewardPerTokenStored;
}

_;
}

constructor(
address _owner,
address _rewardsDistribution,
address _stakingToken,
address _rewardsToken
) Owned(_owner) {
require(OnDemandToken(_rewardsToken).ON_DEMAND_TOKEN(), "rewardsToken must be OnDemandToken");

stakingToken = IERC20(_stakingToken);
rewardsToken = IERC20(_rewardsToken);
rewardsDistribution = _rewardsDistribution;

timeData.rewardsDuration = 2592000;
maxEverTotalRewards = MintableToken(_rewardsToken).maxAllowedTotalSupply();
}

function notifyRewardAmount(
uint256 _reward
) override virtual external whenActive onlyRewardsDistribution updateReward(address(0)) {
Times memory t = timeData;
uint256 newRewardRate;

if (block.timestamp >= t.periodFinish) {
newRewardRate = _reward / t.rewardsDuration;
} else {
uint256 remaining = t.periodFinish - block.timestamp;
uint256 leftover = remaining * rewardRate;
newRewardRate = (_reward + leftover) / t.rewardsDuration;
}

require(newRewardRate != 0, "invalid rewardRate");

rewardRate = newRewardRate;

uint256 totalRewardsSupply = timeData.totalRewardsSupply + _reward;
require(totalRewardsSupply <= maxEverTotalRewards, "rewards overflow");

timeData.totalRewardsSupply = uint96(totalRewardsSupply);
timeData.lastUpdateTime = uint32(block.timestamp);
timeData.periodFinish = uint32(block.timestamp + t.rewardsDuration);

emit RewardAdded(_reward);
}

function setRewardsDuration(uint256 _rewardsDuration) external whenActive onlyOwner {
require(_rewardsDuration != 0, "empty _rewardsDuration");

require(
block.timestamp > timeData.periodFinish,
"Previous period must be complete before changing the duration"
);

timeData.rewardsDuration = uint32(_rewardsDuration);
emit RewardsDurationUpdated(_rewardsDuration);
}

function finishFarming() virtual external whenActive onlyOwner {
Times memory t = timeData;
require(block.timestamp < t.periodFinish, "can't stop if not started or already finished");

stopped = true;

if (_totalSupply != 0) {
uint256 remaining = t.periodFinish - block.timestamp;
timeData.rewardsDuration = uint32(t.rewardsDuration - remaining);
}

timeData.periodFinish = uint32(block.timestamp);

emit FarmingFinished();
}

function exit() override external {
withdraw(_balances[msg.sender]);
getReward();
}

function stake(uint256 amount) override external {
_stake(msg.sender, amount, false);
}

function rescueToken(ERC20 _token, address _recipient, uint256 _amount) external onlyOwner() {
if (address(_token) == address(stakingToken)) {
require(_totalSupply <= stakingToken.balanceOf(address(this)) - _amount, "amount is too big to rescue");
} else if (address(_token) == address(rewardsToken)) {
revert("reward token can not be rescued");
}

_token.transfer(_recipient, _amount);
}

function periodFinish() external view returns (uint256) {
return timeData.periodFinish;
}

function rewardsDuration() external view returns (uint256) {
return timeData.rewardsDuration;
}

function lastUpdateTime() external view returns (uint256) {
return timeData.lastUpdateTime;
}

function balanceOf(address account) override external view returns (uint256) {
return _balances[account];
}

function getRewardForDuration() override external view returns (uint256) {
return rewardRate * timeData.rewardsDuration;
}

function version() external pure virtual returns (uint256) {
return 1;
}

function withdraw(uint256 amount) override public {
_withdraw(amount, msg.sender, msg.sender);
}

function getReward() override public {
_getReward(msg.sender, msg.sender);
}

function totalSupply() override public view returns (uint256) {
return _totalSupply;
}

function lastTimeRewardApplicable() override public view returns (uint256) {
return Math.min(block.timestamp, timeData.periodFinish);
}

function rewardPerToken() override public view returns (uint256) {
if (_totalSupply == 0) {
return rewardPerTokenStored;
}

return rewardPerTokenStored + (
(lastTimeRewardApplicable() - timeData.lastUpdateTime) * rewardRate * 1e18 / _totalSupply
);
}

function earned(address account) override virtual public view returns (uint256) {
return (_balances[account] * (rewardPerToken() - userRewardPerTokenPaid[account]) / 1e18) + rewards[account];
}

function _stake(address user, uint256 amount, bool migration)
internal
nonReentrant
notPaused
updateReward(user)
{
require(timeData.periodFinish != 0, "Stake period not started yet");
require(amount != 0, "Cannot stake 0");

_totalSupply = _totalSupply + amount;
_balances[user] = _balances[user] + amount;

if (migration) {

} else {

require(stakingToken.transferFrom(user, address(this), amount), "token transfer failed");
}

emit Staked(user, amount);
}

function _withdraw(uint256 amount, address user, address recipient) internal nonReentrant updateReward(user) {
require(amount != 0, "Cannot withdraw 0");

_totalSupply = _totalSupply - amount;
_balances[user] = _balances[user] - amount;

require(stakingToken.transfer(recipient, amount), "token transfer failed");

emit Withdrawn(user, amount);
}

function _getReward(address user, address recipient)
internal
virtual
nonReentrant
updateReward(user)
returns (uint256 reward)
{
reward = rewards[user];

if (reward != 0) {
rewards[user] = 0;
OnDemandToken(address(rewardsToken)).mint(recipient, reward);
emit RewardPaid(user, reward);
}
}
}
```

## Fuzzing task — strategy: access_control_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Find missing access control, owner bypasses, and unprotected token issuance.

**Technique:**
Scan the ABI for STATE-MUTATING functions whose names suggest privileged operations (typical name patterns: set*, change*, update*, upgrade*, transferOwnership*, renounce*, pause*, unpause*, emergency*, drain*, rescue*, sweep*, withdraw*, mint*, burn*, initialize*, init* — but use whatever this ABI actually has). Call ALL such functions from attacker_address (an unprivileged caller) — if any succeeds without reverting on auth, that's an access-control bug. Three high-yield sub-cases to ALWAYS try:
  1. SELF-PROMOTION: for address-type arguments pass attacker_address itself (addOwner/setOwner/addMinter/grantRole(attacker)), or address(0).
  2. UNPROTECTED MINT: call mint*/mintTo* with attacker_address as the recipient and a large amount — the witness is the attacker's token balance rising from zero.
  3. SIGNATURE / INITIALIZER BYPASS: many mints are 'guarded' by a signature or proof check that is trivially passed — supply EMPTY values for those args (empty bytes "0x", empty arrays []), and call initialize*/init* directly even on an already-live contract to seize the mint/owner role.
Prefer breadth: try every suspicious setter and every mint/initialize path, not just the most obvious one. DO NOT default to the names in the example below.

**Value hints:** Use "0x0" for amounts, or "0x3635c9adc5dea00000" (large) for mint amounts. For address params, use attacker_address (self) / target_address / address(0) ("0x0") or 40-hex-digit raw addresses. For signature/proof args use empty bytes "0x" or empty arrays [].

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["<UNPROTECTED_INIT_OR_SETTER_FROM_ABI>", [<empty-or-attacker-args>], "0x0", "attacker_address"],
   ["<MINT_FUNC_FROM_ABI>", ["attacker_address", "0x3635c9adc5dea00000"], "0x0", "attacker_address"]]
